    ('01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'Quiz — Ce que la laïcité oblige, et ce qu’elle n’interdit pas', 'EMC', 'Tle', 'Laïcité et démocratie', '60366097-aec5-5a61-bbc6-13396adb5cda'::uuid),
    ('7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'Quiz — Quand la démocratie recule', 'EMC', 'Tle', 'Contestation de la démocratie et transformations des régimes politiques', '8691dd0d-327e-5aaf-bb73-f5afbca72f9d'::uuid),
    ('63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Quiz — Protéger sans détruire ce qu’on protège', 'EMC', 'Tle', 'La protection des démocraties : les enjeux de sécurité', 'fc67cbaf-46c3-5b28-bf77-78e73c0bb4be'::uuid),
    ('ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'Quiz — L’Europe, contrainte et garantie démocratique', 'EMC', 'Tle', 'La construction européenne et la démocratie', '523b1afb-6ff6-5a45-ba89-a7fcef3b1f7d'::uuid),
    ('a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'Quiz — Argumenter, écouter, se contredire', 'EMC', 'Tle', 'Faire vivre le débat dans une démocratie', '420289ad-10d5-5d06-a933-8037d57aab39'::uuid),
    ('5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'Quiz — Ce qu’on exige désormais des élus', 'EMC', 'Tle', 'Le modèle démocratique en question : exemplarité et transparence', '3dc78f98-93ce-57b9-99de-71322b02d948'::uuid),
    ('85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Quiz — Voter n’est pas la seule façon d’agir', 'EMC', 'Tle', 'S’engager dans la démocratie au XXIe siècle', 'e2b4310e-5785-5568-b9eb-09fe79d67959'::uuid),
    ('f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Quiz — Délibérer, tirer au sort, associer', 'EMC', 'Tle', 'Nouvelles aspirations démocratiques', '7609367e-c6eb-5242-ba38-c0de48eeaff4'::uuid),
    ('4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'Quiz — Des droits universels, un monde d’États souverains', 'EMC', 'Tle', 'Conscience démocratique et relations internationales', '3bb5de61-33af-5a2a-a235-f55029c36f46'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
