ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('241d8d63-475b-5c6d-b637-4749d7dc82cf'::uuid, '366b29bc-3e55-5737-b8e6-5efb48978a1b'::uuid, 'Comment étaient désignés la plupart des magistrats à Athènes ?', 'mcq', '["Par tirage au sort","Par élection au suffrage universel","Par hérédité","Par cooptation des riches"]'::jsonb, 0, 'Aristote jugeait l’élection plutôt aristocratique, et le tirage au sort démocratique.', 1),
    ('747c362c-86cc-5972-8775-23c7ce735b98'::uuid, '366b29bc-3e55-5737-b8e6-5efb48978a1b'::uuid, 'Qui était exclu de la citoyenneté à Athènes ?', 'mcq', '["Les femmes, les métèques et les esclaves","Seulement les esclaves","Seulement les étrangers","Les artisans et les paysans"]'::jsonb, 0, 'Environ 40 000 citoyens pour peut-être 300 000 habitants.', 2),
    ('89249b08-4dbb-5f61-be48-e1c71bd5686f'::uuid, '366b29bc-3e55-5737-b8e6-5efb48978a1b'::uuid, 'Quand les femmes obtiennent-elles le droit de vote en France ?', 'mcq', '["En 1944","En 1848","En 1918","En 1965"]'::jsonb, 0, 'Ordonnance de 1944, premier vote effectif en 1945.', 3),
    ('a0185759-e4fa-5cad-b0f0-8ae2459d9760'::uuid, '366b29bc-3e55-5737-b8e6-5efb48978a1b'::uuid, 'Le suffrage universel masculin est instauré en France en…', 'mcq', '["1848","1789","1875","1830"]'::jsonb, 0, 'Il met fin au suffrage censitaire, réservé aux plus imposés.', 4),
    ('6a00dda2-8ec0-54be-b6e7-73162c04d7f0'::uuid, '366b29bc-3e55-5737-b8e6-5efb48978a1b'::uuid, 'Qu’est-ce qu’un suffrage censitaire ?', 'mcq', '["Un droit de vote réservé à ceux qui paient un certain impôt","Un vote par recensement de la population","Un vote obligatoire","Un scrutin indirect"]'::jsonb, 0, 'Il a longtemps réduit le corps électoral à une minorité de propriétaires.', 5),
    ('ddb42121-c1e5-553d-917d-46e3022ef980'::uuid, '366b29bc-3e55-5737-b8e6-5efb48978a1b'::uuid, 'La démocratie athénienne était une démocratie représentative.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle était directe : les citoyens votaient eux-mêmes les lois à l’ecclésia.', 6),
    ('de077dd0-c2af-56d3-9b75-7b912973e551'::uuid, '366b29bc-3e55-5737-b8e6-5efb48978a1b'::uuid, 'Quel texte anglais de 1215 limite le pouvoir du roi ?', 'mcq', '["La Magna Carta","Le Bill of Rights","L’Habeas Corpus","L’Acte d’Union"]'::jsonb, 0, 'Un jalon précoce de la limitation du pouvoir par le droit.', 7),
    ('f87e3691-c443-59bf-befd-fa2866d49819'::uuid, '366b29bc-3e55-5737-b8e6-5efb48978a1b'::uuid, 'Chaque vague de démocratisation a été suivie d’un reflux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui rend l’observation des reculs démocratiques actuels si importante.', 8),
    ('577a3ca4-9c48-57b9-bd5c-0f24dda02977'::uuid, '47d321eb-be02-5d0e-a478-b85a96ad7891'::uuid, 'Selon Rousseau, à qui appartient la souveraineté ?', 'mcq', '["Au peuple, somme des citoyens","À la Nation, entité abstraite","Aux représentants élus","Au chef de l’État"]'::jsonb, 0, 'De là découlent le mandat impératif et la préférence pour la démocratie directe.', 1),
    ('d91399f0-a709-5fdd-b58e-e50e5849b407'::uuid, '47d321eb-be02-5d0e-a478-b85a96ad7891'::uuid, 'Que défend Sieyès avec la souveraineté nationale ?', 'mcq', '["La Nation ne s’exprime que par des représentants","Le peuple doit voter chaque loi","Le roi conserve la souveraineté","Les régions sont souveraines"]'::jsonb, 0, 'Le représentant reçoit un mandat représentatif, sans ordre de ses électeurs.', 2),
    ('0c08f23c-31b2-55fd-9daf-5514c287fd4e'::uuid, '47d321eb-be02-5d0e-a478-b85a96ad7891'::uuid, 'Quel principe, énoncé par Montesquieu, limite le pouvoir par le pouvoir ?', 'mcq', '["La séparation des pouvoirs","La souveraineté populaire","Le suffrage universel","Le contrôle de constitutionnalité"]'::jsonb, 0, 'Exécutif, législatif et judiciaire se limitent mutuellement.', 3),
    ('166aafd7-7aa8-5c06-ae86-f16c4c030659'::uuid, '47d321eb-be02-5d0e-a478-b85a96ad7891'::uuid, 'Que permet la QPC depuis 2010 ?', 'mcq', '["Contester devant le juge une loi déjà en vigueur","Organiser un référendum d’initiative citoyenne","Destituer un élu","Saisir la Cour européenne directement"]'::jsonb, 0, 'La question prioritaire de constitutionnalité ouvre le contrôle aux justiciables.', 4),
    ('9510a6d4-2c60-5cbd-8865-4a6bdfeb48e8'::uuid, '47d321eb-be02-5d0e-a478-b85a96ad7891'::uuid, 'La démocratie se réduit à la règle de la majorité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Des droits fondamentaux limitent ce qu’une majorité peut décider.', 5),
    ('b0ab830f-3a67-5144-8d4b-5656719a3c80'::uuid, '47d321eb-be02-5d0e-a478-b85a96ad7891'::uuid, 'Qu’est-ce que la démocratie participative ?', 'mcq', '["Associer les citoyens aux décisions sans qu’ils tranchent seuls","Faire voter le peuple sur chaque loi","Élire tous les fonctionnaires","Tirer au sort les députés"]'::jsonb, 0, 'Concertations, conventions citoyennes et budgets participatifs en relèvent.', 6),
    ('e23e7966-49b4-5118-bc69-f469c479c1ce'::uuid, '47d321eb-be02-5d0e-a478-b85a96ad7891'::uuid, 'Que signifie l’État de droit ?', 'mcq', '["Les gouvernants eux-mêmes sont soumis au droit","L’État peut tout décider","Le droit est fixé par la majorité","La justice dépend du gouvernement"]'::jsonb, 0, 'C’est ce qui distingue un pouvoir légitime d’un pouvoir arbitraire.', 7),
    ('5a5cdb52-8399-513f-918b-414f3b32bff1'::uuid, '47d321eb-be02-5d0e-a478-b85a96ad7891'::uuid, 'La Constitution française combine souveraineté nationale et souveraineté populaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le peuple l’exerce « par ses représentants et par la voie du référendum ».', 8),
    ('94a13aad-d1f0-5b90-b5b5-d3a7321a08f0'::uuid, '4a1655d9-9854-5b40-b0e4-0b328714fa00'::uuid, 'Quel mode de scrutin dégage le plus facilement une majorité stable ?', 'mcq', '["Le scrutin majoritaire","La proportionnelle intégrale","Le vote préférentiel","Le tirage au sort"]'::jsonb, 0, 'Au prix d’une sous-représentation des courants minoritaires.', 1),
    ('651742cc-4f82-52f3-8937-59269df37def'::uuid, '4a1655d9-9854-5b40-b0e4-0b328714fa00'::uuid, 'Comment sont élus les sénateurs français ?', 'mcq', '["Au suffrage universel indirect","Au suffrage universel direct","Par tirage au sort","Par nomination présidentielle"]'::jsonb, 0, 'Par un collège de grands électeurs, essentiellement des élus locaux.', 2),
    ('bf8c6b20-3988-5b32-8025-4d21ba85f6cb'::uuid, '4a1655d9-9854-5b40-b0e4-0b328714fa00'::uuid, 'Le vote est-il obligatoire en France ?', 'mcq', '["Non, il est libre","Oui, sous peine d’amende","Oui, pour la présidentielle seulement","Oui, depuis 2017"]'::jsonb, 0, 'Il l’est en Belgique et en Australie, pas en France.', 3),
    ('f17f92af-f455-5768-a88a-e6ffb10c9888'::uuid, '4a1655d9-9854-5b40-b0e4-0b328714fa00'::uuid, 'Quel organisme contrôle les comptes de campagne ?', 'mcq', '["La CNCCFP","L’Arcom","La CNIL","La HATVP"]'::jsonb, 0, 'L’Arcom veille, elle, à l’équité du temps de parole.', 4),
    ('e5e395c1-63b2-503b-81dc-8225eb6c24b6'::uuid, '4a1655d9-9854-5b40-b0e4-0b328714fa00'::uuid, 'La proportionnelle reflète mieux l’opinion mais peut fragmenter l’assemblée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où les systèmes mixtes, qui ajoutent une prime majoritaire.', 5),
    ('fa45a7d1-104c-50bf-89bc-744a734dcf0f'::uuid, '4a1655d9-9854-5b40-b0e4-0b328714fa00'::uuid, 'Qu’appelle-t-on la mal-inscription ?', 'mcq', '["Être inscrit sur les listes d’une commune où l’on ne vit plus","Voter deux fois","Ne pas être inscrit du tout","Se tromper de bulletin"]'::jsonb, 0, 'Elle gonfle mécaniquement l’abstention mesurée.', 6),
    ('782baa2e-8d0c-5aa4-a825-c8d381fe7f2d'::uuid, '4a1655d9-9854-5b40-b0e4-0b328714fa00'::uuid, 'Il existe un mode de scrutin politiquement neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chaque mode arbitre entre représentativité et gouvernabilité : c’est un choix politique.', 7),
    ('a9189915-6ab7-504e-a3b1-5bf2c94efdfb'::uuid, '4a1655d9-9854-5b40-b0e4-0b328714fa00'::uuid, 'Quelle réforme de 2000 a rapproché législatives et présidentielle ?', 'mcq', '["Le passage au quinquennat","Le non-cumul des mandats","La parité","La réforme du Sénat"]'::jsonb, 0, 'Avec l’inversion du calendrier, les législatives suivent la présidentielle.', 8),
    ('7d01209d-e087-512d-a9f1-7745265cdea3'::uuid, '01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'Que garantissent les deux premiers articles de la loi de 1905 ?', 'mcq', '["La liberté de conscience et le libre exercice des cultes","L’interdiction des religions dans l’espace public","Le financement des cultes par l’État","La suppression des jours fériés religieux"]'::jsonb, 0, 'Et, dans le même mouvement, la neutralité de l’État qui ne salarie aucun culte.', 1),
    ('0210ab44-0290-5135-a23f-56b0092bc705'::uuid, '01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'À qui s’applique l’obligation de neutralité religieuse ?', 'mcq', '["Aux agents publics dans leurs fonctions","À tous les citoyens dans la rue","Aux seuls enseignants","Aux entreprises privées"]'::jsonb, 0, 'Un usager du service public, lui, n’y est pas soumis.', 2),
    ('fd120dfc-64f9-549a-b5c7-55ac7774c02a'::uuid, '01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'Que prévoit la loi de 2004 ?', 'mcq', '["L’interdiction des signes religieux ostensibles dans les écoles publiques","L’interdiction du voile dans la rue","La fin du concordat en Alsace-Moselle","La neutralité des entreprises"]'::jsonb, 0, 'Elle vise les élèves des écoles, collèges et lycées publics.', 3),
    ('356fe135-959a-5c99-91d1-b49f28ed0d8f'::uuid, '01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'Le blasphème est-il un délit en droit français ?', 'mcq', '["Non","Oui, depuis 1905","Oui, depuis 2021","Oui, pour certaines religions"]'::jsonb, 0, 'La critique des idées religieuses est libre ; l’injure envers des personnes ne l’est pas.', 4),
    ('6a10c740-d4a4-52a5-a4ac-2268fed07b40'::uuid, '01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'Laïcité et athéisme d’État sont deux choses différentes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’État n’est pas contre les religions : il est neutre entre elles.', 5),
    ('53e2b60e-ecee-5680-80cf-1f1faeaf96c2'::uuid, '01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'Quel territoire français conserve un régime concordataire ?', 'mcq', '["L’Alsace-Moselle","La Corse","La Guyane","Mayotte"]'::jsonb, 0, 'Annexée en 1905, elle n’a pas connu l’application de la loi de séparation.', 6),
    ('4c85c0fa-1345-5c4d-94b7-937adca40d46'::uuid, '01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'Qu’a renforcé la loi du 24 août 2021 ?', 'mcq', '["La neutralité dans les missions de service public et le contrôle des associations","L’interdiction des signes religieux dans la rue","Le financement des cultes","La suppression de l’instruction en famille"]'::jsonb, 0, 'Elle encadre aussi plus strictement l’instruction en famille.', 7),
    ('cb0915bb-e803-5037-b445-91321de17f87'::uuid, '01fa116c-aafb-5de6-85f3-3b048b920095'::uuid, 'Un particulier peut porter un signe religieux dans la rue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La neutralité s’impose à l’État et à ses agents, pas aux usagers dans l’espace public.', 8),
    ('ac726746-1365-5ba7-a129-d99efec8be20'::uuid, '7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'Qu’est-ce qu’une démocratie illibérale ?', 'mcq', '["Un régime qui garde les formes électorales mais vide les contre-pouvoirs","Une démocratie sans élections","Une monarchie constitutionnelle","Un régime militaire"]'::jsonb, 0, 'Justice sous tutelle, médias contrôlés, société civile harcelée.', 1),
    ('ecc2125f-cfb2-541a-98b0-b0a12a122575'::uuid, '7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'Qu’est-ce qui distingue un régime totalitaire d’un régime autoritaire ?', 'mcq', '["Il prétend contrôler la société entière avec une idéologie officielle","Il organise des élections","Il tolère une opposition","Il respecte la justice"]'::jsonb, 0, 'Parti unique, idéologie obligatoire, terreur organisée.', 2),
    ('8d05872e-0abb-5006-bd14-212c4a30f8ab'::uuid, '7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'Les indices internationaux constatent une progression continue des démocraties.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'V-Dem et Freedom House mesurent au contraire un recul depuis une quinzaine d’années.', 3),
    ('47050472-10f8-5264-801a-2b434b4a1600'::uuid, '7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'Comment une démocratie est-elle aujourd’hui le plus souvent affaiblie ?', 'mcq', '["De l’intérieur, en respectant les formes","Par un coup d’État militaire","Par une invasion étrangère","Par un référendum de dissolution"]'::jsonb, 0, 'Ce qui rend le recul difficile à dater et à contester juridiquement.', 4),
    ('96c1f420-c7ee-5d60-9d99-bc9824d67b68'::uuid, '7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'Quel pays européen est le plus souvent cité comme démocratie illibérale ?', 'mcq', '["La Hongrie","Le Portugal","L’Irlande","La Suède"]'::jsonb, 0, 'La Turquie est un autre cas fréquemment analysé.', 5),
    ('d626b147-ab0d-5690-a23f-476cd819b425'::uuid, '7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'Quel facteur alimente la contestation des démocraties ?', 'mcq', '["La défiance envers les élus et le sentiment que le vote ne change rien","La hausse de la participation électorale","Le renforcement des contre-pouvoirs","La stabilité des majorités"]'::jsonb, 0, 'S’y ajoutent les inégalités et la désinformation.', 6),
    ('79b7633f-6a77-587a-8997-fd2f2f34c475'::uuid, '7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'Qu’est-ce qui mesure le mieux la résilience d’une démocratie ?', 'mcq', '["L’existence réelle de contre-pouvoirs indépendants","La longueur de sa Constitution","Le nombre de partis","La fréquence des référendums"]'::jsonb, 0, 'Les textes ne suffisent pas : ce sont les contre-pouvoirs effectifs qui tiennent.', 7),
    ('d3d6d2b8-7d8a-5edb-976f-d092ef4a4a40'::uuid, '7ba5f44a-33d1-5239-9a2b-1f0c2071fd87'::uuid, 'La Chine met en avant un modèle fondé sur l’efficacité plutôt que sur le pluralisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des ressorts de la contestation du modèle démocratique à l’échelle mondiale.', 8),
    ('32fa4924-98ba-5729-ae90-a185f496ccb7'::uuid, '63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Quand l’état d’urgence a-t-il été déclaré en France après les attentats ?', 'mcq', '["En novembre 2015","En janvier 2015","En juillet 2016","En 2017"]'::jsonb, 0, 'Il a été prolongé jusqu’à son remplacement partiel par la loi SILT en 2017.', 1),
    ('0b911626-04e6-5106-8c69-7f948755afaf'::uuid, '63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Que permet une perquisition administrative sous état d’urgence ?', 'mcq', '["Une perquisition décidée sans autorisation d’un juge","Une perquisition ordonnée par un juge d’instruction","Une fouille des seuls lieux publics","Une garde à vue prolongée"]'::jsonb, 0, 'C’est précisément ce qui la distingue du droit commun — et ce qui la rend contestée.', 2),
    ('61e6eaa2-4b69-5704-a93c-54ca9694b6c4'::uuid, '63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Quelle loi de 2017 fait passer des mesures d’exception dans le droit commun ?', 'mcq', '["La loi SILT","La loi renseignement","La loi Informatique et libertés","La loi de 1905"]'::jsonb, 0, 'Sous contrôle du juge administratif.', 3),
    ('8f6d33ca-2c82-5125-8fc8-64e5bd4f8f50'::uuid, '63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Quelle autorité protège les données personnelles en France ?', 'mcq', '["La CNIL","La HATVP","L’Arcom","La CNCCFP"]'::jsonb, 0, 'Elle contrôle notamment les fichiers et les dispositifs de surveillance.', 4),
    ('d2d0802f-ba64-5d78-a8e2-000296379f97'::uuid, '63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Le Conseil constitutionnel a censuré certaines mesures antiterroristes jugées excessives.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des garde-fous du contrôle de proportionnalité.', 5),
    ('0c020f91-7b69-5fb9-88d7-37efd797fb53'::uuid, '63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Quels critères permettent d’apprécier une mesure de sécurité ?', 'mcq', '["Nécessité, proportionnalité, contrôle par un juge","Rapidité, coût, efficacité","Popularité, urgence, durée","Légalité seule"]'::jsonb, 0, 'C’est la grille attendue dans une copie d’EMC.', 6),
    ('81cadf67-dd05-5d83-a940-7ab74fa88b1a'::uuid, '63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Qu’appelle-t-on ingérence étrangère ?', 'mcq', '["Une opération d’influence ou de manipulation venue d’un autre État","Une immigration non contrôlée","Un investissement étranger","Une aide au développement"]'::jsonb, 0, 'Manipulation de l’information et financements occultes en sont les formes courantes.', 7),
    ('a1f840e9-9914-57a5-87d6-24561f0b1fdf'::uuid, '63242696-e242-5d50-aa38-ddf83d2d6406'::uuid, 'Un régime d’exception peut devenir permanent sans changer la nature du régime politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une exception permanente et sans contrôle transforme le régime lui-même.', 8),
    ('c9a1bcb1-029e-5ed6-8c32-38be81b53b3b'::uuid, 'ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'Que fixent les critères de Copenhague de 1993 ?', 'mcq', '["Les conditions démocratiques d’adhésion à l’Union","Les règles budgétaires de la zone euro","Les quotas migratoires","Le fonctionnement de la BCE"]'::jsonb, 0, 'Institutions stables, État de droit, droits de l’homme, protection des minorités.', 1),
    ('1b68c89f-75ef-5859-b1ee-26bb605d013b'::uuid, 'ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'Depuis quand le Parlement européen est-il élu au suffrage universel direct ?', 'mcq', '["1979","1957","1992","2009"]'::jsonb, 0, 'Ses pouvoirs se sont ensuite considérablement étendus.', 2),
    ('6b8b63b2-18db-5965-98c7-6bf5048d84c9'::uuid, 'ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'Que permet l’article 7 du traité sur l’Union européenne ?', 'mcq', '["Sanctionner un État qui s’écarte des valeurs communes","Sortir de l’Union","Créer une armée commune","Suspendre l’euro"]'::jsonb, 0, 'L’unanimité requise le rend très difficile à appliquer — d’où la conditionnalité budgétaire.', 3),
    ('b7e8b5af-481d-5c6f-b1b2-87fe028a977d'::uuid, 'ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'Quelle institution européenne détient l’initiative législative ?', 'mcq', '["La Commission","Le Parlement","Le Conseil","La CJUE"]'::jsonb, 0, 'C’est l’un des arguments avancés pour parler de déficit démocratique.', 4),
    ('0071760a-2845-545b-a5df-686b23122906'::uuid, 'ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'Que permet l’initiative citoyenne européenne ?', 'mcq', '["Demander à la Commission de légiférer avec un million de signatures","Organiser un référendum européen","Destituer un commissaire","Élire le président de la Commission"]'::jsonb, 0, 'Les signatures doivent venir d’au moins sept États membres.', 5),
    ('e574a14f-207f-5d35-b8c3-d856ec05bdda'::uuid, 'ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'L’adhésion à l’Union a servi d’ancrage démocratique après des dictatures.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Espagne, Portugal, Grèce, puis les pays d’Europe centrale après 1989.', 6),
    ('12bb6259-34c9-554a-9145-49e1476a4225'::uuid, 'ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'Depuis quand la Charte des droits fondamentaux a-t-elle valeur contraignante ?', 'mcq', '["2009","2000","1993","2016"]'::jsonb, 0, 'Avec l’entrée en vigueur du traité de Lisbonne.', 7),
    ('49c0705c-640a-5432-a882-c23425be933a'::uuid, 'ab62d378-6e83-5da1-841c-7bb0adfee22b'::uuid, 'Aucune décision européenne n’est prise par des responsables issus d’élections.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles le sont par des députés élus ou par des gouvernements responsables devant leurs Parlements.', 8),
    ('574b5f9c-9911-521a-aad7-63daed395e8b'::uuid, 'a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'Qu’est-ce qu’argumenter ?', 'mcq', '["Appuyer une position sur des raisons et des faits vérifiables","Répéter son opinion avec conviction","Convaincre par tous les moyens","Éviter le désaccord"]'::jsonb, 0, 'Sans raisons vérifiables, il n’y a pas de débat mais une confrontation d’affirmations.', 1),
    ('bad13781-2319-5e9c-a258-fae80bb57ba0'::uuid, 'a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'Quel philosophe a théorisé la notion d’espace public ?', 'mcq', '["Habermas","Montesquieu","Rousseau","Tocqueville"]'::jsonb, 0, 'Le lieu où les citoyens discutent publiquement des affaires communes.', 2),
    ('efc9b0a9-b68b-5a6a-9a03-0f863cd9c4f2'::uuid, 'a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'Qu’est-ce qu’une bulle de filtre ?', 'mcq', '["Une exposition sélective à des contenus qui confirment nos opinions","Un filtre anti-spam","Une censure d’État","Un dispositif de fact-checking"]'::jsonb, 0, 'Les algorithmes privilégient ce qui confirme et ce qui indigne.', 3),
    ('50731537-0fef-5756-aa32-77c07592af54'::uuid, 'a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'Combien de citoyens tirés au sort composaient la Convention citoyenne pour le climat ?', 'mcq', '["150","50","500","1 000"]'::jsonb, 0, 'Une expérimentation majeure de délibération citoyenne en France.', 4),
    ('41740847-2ee6-527e-b552-bc4b62c1f896'::uuid, 'a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'Un désaccord argumenté est utile à la démocratie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le désaccord non argumenté, ou l’absence de débat, qui l’abîme.', 5),
    ('60af97ae-ac76-5588-a9be-5b6c4db7c492'::uuid, 'a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'Qu’est-ce qu’un sophisme ?', 'mcq', '["Un raisonnement trompeur qui a l’apparence de la logique","Une opinion minoritaire","Une information fausse","Un argument d’autorité valide"]'::jsonb, 0, 'Attaque personnelle, faux dilemme et généralisation abusive en sont des formes courantes.', 6),
    ('a346bab2-95f4-52de-a4c6-c84c1b4874ea'::uuid, 'a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'La désinformation circule généralement plus vite que sa correction.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’une des difficultés structurelles de l’espace informationnel actuel.', 7),
    ('25d3ac73-50bd-55db-baaf-921ba2bf85dd'::uuid, 'a8828cf1-043c-5e6e-923f-31acc0842688'::uuid, 'Que vise l’éducation aux médias et à l’information ?', 'mcq', '["Apprendre à vérifier et à hiérarchiser l’information","Interdire les réseaux sociaux aux mineurs","Former des journalistes","Contrôler les contenus en ligne"]'::jsonb, 0, 'Elle est inscrite dans les programmes scolaires.', 8),
    ('83740ec1-1aec-575a-9121-f1acd0eec3a4'::uuid, '5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'Quelle autorité contrôle les déclarations de patrimoine des responsables publics ?', 'mcq', '["La HATVP","La CNIL","La Cour des comptes","Le Conseil constitutionnel"]'::jsonb, 0, 'Créée en 2013 après l’affaire Cahuzac.', 1),
    ('4e7e6421-3917-54cb-83cf-dd8d9139655b'::uuid, '5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'Qu’interdisent les lois de 2017 pour la confiance dans la vie politique ?', 'mcq', '["Les emplois familiaux des parlementaires","Le financement public des partis","Le lobbying","Le cumul de deux mandats locaux"]'::jsonb, 0, 'Elles suppriment aussi la réserve parlementaire et encadrent les frais de mandat.', 2),
    ('074d31fe-462f-5252-a1be-e36756f8617f'::uuid, '5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'Qu’est-ce qu’un conflit d’intérêts ?', 'mcq', '["Une situation où un intérêt privé peut influencer une fonction publique","Un désaccord entre deux ministères","Une grève dans le service public","Un litige commercial"]'::jsonb, 0, 'Il doit être déclaré, et la personne concernée doit se déporter.', 3),
    ('062e3ab4-cc58-5db8-a5ff-51ad8deef452'::uuid, '5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'Quelle loi de 2016 protège les lanceurs d’alerte ?', 'mcq', '["La loi Sapin II","La loi SILT","La loi Informatique et libertés","La loi de 1905"]'::jsonb, 0, 'Renforcée en 2022 par la transposition d’une directive européenne.', 4),
    ('497d70a4-7911-57e9-9c3f-cd01cedf92c1'::uuid, '5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'Les lobbyistes doivent s’inscrire sur un répertoire public.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Tenu par la HATVP, il oblige à déclarer les actions d’influence menées.', 5),
    ('e3156f07-25de-54e2-8988-e699b7169a5d'::uuid, '5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'Quelle institution contrôle l’emploi des fonds publics ?', 'mcq', '["La Cour des comptes","La HATVP","Le Conseil d’État","L’Arcom"]'::jsonb, 0, 'Ses rapports publics alimentent le débat démocratique.', 6),
    ('1a82da53-fc11-5bfb-933d-0edab389ff97'::uuid, '5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'Le non-cumul entre mandat parlementaire et exécutif local s’applique depuis…', 'mcq', '["2017","2013","2008","2022"]'::jsonb, 0, 'Une transformation importante du métier de parlementaire.', 7),
    ('479389b3-1db3-50f9-aa90-129f6dadacef'::uuid, '5661509d-9cdb-5b6c-a454-1f66ae120c85'::uuid, 'La transparence garantit à elle seule la probité des élus.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle rend le contrôle possible ; elle ne remplace ni la déontologie ni la sanction.', 8),
    ('5447f3df-1f88-5e84-b2ef-2c3a9c178af1'::uuid, '85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Quelle est aujourd’hui la première forme d’engagement en France ?', 'mcq', '["Le bénévolat associatif","L’adhésion à un parti","La syndicalisation","La pétition en ligne"]'::jsonb, 0, 'Plus d’un million d’associations et de l’ordre de 20 millions de bénévoles.', 1),
    ('21471099-a5a3-5135-b3fc-3c6bde85040e'::uuid, '85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Quel est l’ordre de grandeur du taux de syndicalisation en France ?', 'mcq', '["Environ 10 %","Environ 40 %","Environ 25 %","Environ 60 %"]'::jsonb, 0, 'L’un des plus faibles d’Europe, alors que la couverture des accords y est très large.', 2),
    ('f07ef073-1d3e-50ce-9c61-afc08946c52a'::uuid, '85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Qu’est-ce que la désobéissance civile ?', 'mcq', '["Violer publiquement et sans violence une règle jugée injuste, en acceptant la sanction","Refuser de payer ses impôts en secret","Manifester sans autorisation","Voter blanc"]'::jsonb, 0, 'Thoreau, Gandhi et Martin Luther King en sont les références classiques.', 3),
    ('4ada4ff7-ed7a-5a4b-a1a7-d3d1b2291094'::uuid, '85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Depuis quelle année existe le service civique ?', 'mcq', '["2010","1997","2000","2016"]'::jsonb, 0, 'Ouvert aux 16-25 ans, pour des missions d’intérêt général.', 4),
    ('97373bdb-e100-53a5-884a-7c3577935d7f'::uuid, '85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Qu’appelle-t-on le « slacktivisme » ?', 'mcq', '["Un engagement en ligne sans effort ni effet réel","Un militantisme syndical radical","Un boycott organisé","Une grève illimitée"]'::jsonb, 0, 'Ce qui fait la différence : la continuité de l’action et son ancrage collectif.', 5),
    ('5244d2a8-f632-538b-82a9-576528a8c08b'::uuid, '85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Les effectifs des partis politiques ont fortement diminué en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’engagement se reporte vers des formes plus ponctuelles et choisies.', 6),
    ('9ea5520b-93d9-5af8-84d6-69f70e037477'::uuid, '85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Qu’est-ce qu’un budget participatif ?', 'mcq', '["Une part du budget local dont l’affectation est décidée par les habitants","Le budget de l’État voté par référendum","Une cagnotte associative","Le financement participatif d’une entreprise"]'::jsonb, 0, 'Une forme concrète de démocratie participative locale.', 7),
    ('1cffdeb4-0ec5-524d-8da8-568ddc0314d8'::uuid, '85740ba6-faa2-5ec0-913a-f73b774871e5'::uuid, 'Une pétition en ligne ne peut avoir aucun effet institutionnel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une pétition massive peut porter un sujet jusqu’au Parlement.', 8),
    ('6f218153-bcc8-5da4-b056-e7bf79f6684f'::uuid, 'f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Sur quel pari repose la démocratie délibérative ?', 'mcq', '["Une décision précédée d’une délibération informée est plus légitime","La majorité a toujours raison","Les experts doivent décider seuls","Le vote suffit à légitimer"]'::jsonb, 0, 'D’où les panels de citoyens tirés au sort et formés avant de délibérer.', 1),
    ('784a35cd-158d-5750-8185-26641cad54ef'::uuid, 'f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Quel est l’avantage du tirage au sort par rapport à l’élection ?', 'mcq', '["Il assure une diversité sociale que l’élection ne produit pas","Il donne un mandat plus fort","Il coûte moins cher","Il évite tout débat"]'::jsonb, 0, 'En revanche, il ne confère pas de mandat : le sort des propositions reste la difficulté.', 2),
    ('647fdc4e-3f02-58fa-b77e-037d076bc085'::uuid, 'f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Quel référendum existe en droit français depuis 2008 ?', 'mcq', '["Le référendum d’initiative partagée","Le référendum d’initiative citoyenne","Le référendum révocatoire","Le référendum local obligatoire"]'::jsonb, 0, 'Ses seuils, très élevés, n’ont jamais été franchis jusqu’au bout.', 3),
    ('293609df-caff-5105-b5d3-ae4660f14a56'::uuid, 'f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Que garantit la Charte de l’environnement adossée à la Constitution en 2005 ?', 'mcq', '["Un droit à l’information et à la participation du public","L’interdiction des énergies fossiles","Un droit de veto écologique","La neutralité carbone"]'::jsonb, 0, 'Elle fonde la démocratie environnementale en droit français.', 4),
    ('f6a9f270-35e5-55ad-b534-84071a67321f'::uuid, 'f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Un budget participatif laisse les habitants décider d’une part du budget local.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la forme la plus répandue de démocratie participative locale.', 5),
    ('2771531c-b813-549d-8ab5-9ba894aaa1bd'::uuid, 'f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Quelle convention citoyenne a réuni 150 personnes tirées au sort en 2019-2020 ?', 'mcq', '["La Convention citoyenne pour le climat","La Convention sur la fin de vie","Le Grand Débat national","La Conférence sur l’avenir de l’Europe"]'::jsonb, 0, 'Ses propositions ont été partiellement reprises, ce qui a nourri le débat sur les suites données.', 6),
    ('55806e43-4c12-5e83-ab38-4f186a2056b2'::uuid, 'f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Une consultation citoyenne sans suite renforce la confiance envers les institutions.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle produit l’inverse : la déception aggrave la défiance qu’elle prétendait réduire.', 7),
    ('7ad82949-d2f9-5f9f-8d96-26156f80752e'::uuid, 'f43e1a78-519c-54ef-8387-2ac618634468'::uuid, 'Que désigne la civic tech ?', 'mcq', '["Les outils numériques de consultation et de participation citoyenne","La surveillance algorithmique","Le vote électronique obligatoire","Les réseaux sociaux politiques"]'::jsonb, 0, 'Elle facilite la consultation, sans régler la question du suivi des avis recueillis.', 8),
    ('f54686e4-4938-5775-af07-b25f25172fcb'::uuid, '4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'En quelle année la Déclaration universelle des droits de l’homme est-elle adoptée ?', 'mcq', '["1948","1945","1950","1966"]'::jsonb, 0, 'Par l’Assemblée générale de l’ONU : une référence sans force contraignante.', 1),
    ('e94a1220-b74d-525f-ad3c-0166e606a7b1'::uuid, '4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'Quelle cour peut condamner un État sur requête d’un individu ?', 'mcq', '["La Cour européenne des droits de l’homme","La Cour pénale internationale","La Cour internationale de justice","La CJUE"]'::jsonb, 0, 'Elle applique la Convention européenne des droits de l’homme de 1950.', 2),
    ('9f22d2d7-a446-53b0-8356-3386474363bb'::uuid, '4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'Que juge la Cour pénale internationale ?', 'mcq', '["Des individus, pour les crimes les plus graves","Des États, pour violation de traités","Des entreprises","Des organisations internationales"]'::jsonb, 0, 'Génocide, crimes contre l’humanité, crimes de guerre, crime d’agression.', 3),
    ('285e56df-b434-5e84-925d-8b156e0a2178'::uuid, '4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'Toutes les grandes puissances ont ratifié le statut de Rome.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'États-Unis, Chine, Russie et Inde ne l’ont pas ratifié — une limite majeure.', 4),
    ('d7f15807-edd6-5d77-95c3-0f4b06b37143'::uuid, '4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'Qu’est-ce que la responsabilité de protéger, adoptée en 2005 ?', 'mcq', '["Le principe autorisant la communauté internationale à agir quand un État massacre sa population","L’obligation d’accueillir des réfugiés","La protection des ambassades","Le devoir d’aide au développement"]'::jsonb, 0, 'Son application dépend du Conseil de sécurité, donc du droit de veto.', 5),
    ('fa3173c9-49a1-5355-ae6e-340c7e656ed6'::uuid, '4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'Quel mécanisme bloque souvent l’action du Conseil de sécurité ?', 'mcq', '["Le droit de veto des cinq membres permanents","Le vote à la majorité qualifiée","L’absence de budget","Le retrait des ONG"]'::jsonb, 0, 'Il a notamment paralysé l’action sur la Syrie.', 6),
    ('66d27154-22cf-514f-b683-e0bdaa9d19e2'::uuid, '4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'Quel est le principal pouvoir des ONG de défense des droits humains ?', 'mcq', '["Documenter et alerter l’opinion","Sanctionner les États","Arrêter les responsables","Voter à l’ONU"]'::jsonb, 0, 'Leurs rapports pèsent par la preuve et la réputation, non par la contrainte.', 7),
    ('25db9065-37e4-5ff3-a390-8de9f35c3c4b'::uuid, '4679ad72-acaa-5706-a891-a506c6b909be'::uuid, 'La promotion de la démocratie par la force a produit des résultats contrastés.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ancrage réussi par l’élargissement européen, échecs coûteux là où elle a été imposée militairement.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('emc');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('emc')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 230 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 230 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
